"""JSON file storage for tasks. Data file format: {"next_id": int, "tasks": [...]}."""
import json
import os
from pathlib import Path

DEFAULT_PATH = Path(os.environ.get("TASKS_FILE", "tasks.json"))


class TaskError(Exception):
    pass


def load(path=DEFAULT_PATH):
    if not Path(path).exists():
        return {"next_id": 1, "tasks": []}
    with open(path, encoding="utf-8") as handle:
        return json.load(handle)


def save(data, path=DEFAULT_PATH):
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(data, handle, indent=2)


def add(title, path=DEFAULT_PATH):
    data = load(path)
    task = {"id": data["next_id"], "title": title, "done": False}
    data["tasks"].append(task)
    data["next_id"] += 1
    save(data, path)
    return task


def complete(task_id, path=DEFAULT_PATH):
    data = load(path)
    for task in data["tasks"]:
        if task["id"] == task_id:
            task["done"] = True
            save(data, path)
            return task
    raise TaskError(f"no task {task_id}")

"""python -m tasks add TITLE | list | done ID"""
import argparse
import sys

from . import store


def main(argv=None):
    parser = argparse.ArgumentParser(prog="tasks")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("add").add_argument("title")
    sub.add_parser("list")
    sub.add_parser("done").add_argument("id", type=int)
    args = parser.parse_args(argv)
    try:
        if args.command == "add":
            print(store.add(args.title)["id"])
        elif args.command == "list":
            for task in store.load()["tasks"]:
                print(f"{task['id']:>3} [{'x' if task['done'] else ' '}] {task['title']}")
        elif args.command == "done":
            store.complete(args.id)
    except store.TaskError as exc:
        print(exc, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

import os
import tempfile
import unittest
from pathlib import Path

from tasks import store


class StoreTest(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.TemporaryDirectory()
        self.path = Path(self.dir.name) / "tasks.json"

    def tearDown(self):
        self.dir.cleanup()

    def test_add_and_complete(self):
        task = store.add("write tests", self.path)
        store.complete(task["id"], self.path)
        self.assertTrue(store.load(self.path)["tasks"][0]["done"])

    def test_complete_unknown(self):
        with self.assertRaises(store.TaskError):
            store.complete(42, self.path)


if __name__ == "__main__":
    unittest.main()

